// Compiled to WebAssembly before publication. Runs inside your browser.
// The host reads HTTP/RBH1 and supplies x, y, z (metres), then w, x, y, z.
extern "C" int neo_read_pose(double *values);
extern "C" void neo_write_pose(const double *values);

extern "C" int run_step() {
    double pose[7];
    if (!neo_read_pose(pose)) return 0;
    double result[10];
    for (int i = 0; i < 7; ++i) result[i] = pose[i];
    for (int i = 0; i < 3; ++i) result[7 + i] = pose[i] * 1000.0;
    // Host displays metres, w/x/y/z orientation and millimetres.
    neo_write_pose(result);
    return 1;
}

