#[link(wasm_import_module = "env")]
extern "C" {
    fn neo_read_pose(values: *mut f64) -> i32;
    fn neo_write_pose(values: *const f64);
}

#[no_mangle]
pub extern "C" fn run_step() -> i32 {
    let mut pose = [0.0_f64; 7];
    if unsafe { neo_read_pose(pose.as_mut_ptr()) } == 0 { return 0; }
    let mut result = [0.0_f64; 10];
    result[..7].copy_from_slice(&pose);
    for i in 0..3 { result[7 + i] = pose[i] * 1000.0; }
    unsafe { neo_write_pose(result.as_ptr()); }
    1
}

